arguments.command:
cat << 'EOF' > /app/output/styles.css
:root {
  --primary: #171717;
  --accent: #0072F5;
  --bg: #FAFAFA;
  --text-main: #171717;
  --text-muted: #666;
  --border: #eaeaea;
  --card-bg: #fff;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  background-color: var(--bg);
  color: var(--text-main);
  line-height: 1.6;
}
a { text-decoration: none; color: inherit; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul { list-style: none; }

.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

header {
  border-bottom: 1px solid var(--border);
  background: var(--card-bg);
  position: sticky; top: 0; z-index: 100;
}
.nav-inner {
  display: flex; justify-content: space-between; align-items: center; height: 64px;
}
.logo { font-weight: 800; font-size: 1.25rem; letter-spacing: -0.02em; }
.nav-links { display: none; gap: 24px; align-items: center; height: 100%; }
@media (min-width: 800px) { .nav-links { display: flex; } }
.nav-links li { position: relative; height: 100%; display: flex; align-items: center; }
.nav-link { font-size: 0.9rem; color: var(--text-muted); transition: color 0.2s; font-weight: 500; cursor: pointer;}
.nav-link:hover { color: var(--text-main); }

.dropdown-menu {
  display: none; position: absolute; top: 100%; left: 50%; transform: translateX(-50%);
  background: var(--card-bg); border: 1px solid var(--border); border-radius: 8px;
  padding: 24px; width: max-content; box-shadow: 0 10px 30px rgba(0,0,0,0.05);
  opacity: 0; pointer-events: none; transition: opacity 0.2s, transform 0.2s;
  margin-top: 0px;
}
.nav-links li:hover .dropdown-menu {
  display: flex; opacity: 1; pointer-events: auto; transform: translateX(-50%) translateY(0);
}
.dropdown-group { margin-right: 48px; min-width: 160px; }
.dropdown-group:last-child { margin-right: 0; }
.dropdown-title { font-weight: 600; font-size: 0.75rem; margin-bottom: 16px; text-transform: uppercase; color: var(--text-muted); letter-spacing: 0.05em; }
.dropdown-item { display: block; padding: 6px 0; font-size: 0.9rem; color: var(--text-main); }
.dropdown-item:hover { color: var(--accent); }
.dropdown-desc { font-size: 0.8rem; color: var(--text-muted); display: block; margin-top: 2px; line-height: 1.3; }

.nav-actions { display: flex; gap: 12px; align-items: center; }
.btn { padding: 8px 16px; border-radius: 6px; font-weight: 500; font-size: 0.9rem; transition: all 0.2s; }
.btn-outline { border: 1px solid var(--border); }
.btn-outline:hover { border-color: var(--primary); }
.btn-primary { background: var(--primary); color: #fff; }
.btn-primary:hover { background: #333; }
.btn-icon { padding: 8px; display: flex; align-items: center; justify-content: center; }

.hero { padding: 64px 0 48px; }
.hero-title { font-size: 3rem; font-weight: 800; margin-bottom: 16px; letter-spacing: -0.03em; }
.hero-subtitle { font-size: 1.25rem; color: var(--text-muted); max-width: 600px; }

.featured-grid { display: grid; grid-template-columns: 1fr; gap: 24px; margin-bottom: 64px; }
@media (min-width: 900px) {
  .featured-grid { grid-template-columns: 2fr 1fr; grid-template-rows: 1fr 1fr; }
  .featured-main { grid-column: 1 / 2; grid-row: 1 / 3; }
}

.card {
  background: var(--card-bg); border: 1px solid var(--border); border-radius: 12px;
  padding: 24px; transition: transform 0.2s, box-shadow 0.2s;
  display: flex; flex-direction: column; height: 100%; text-align: left;
}
.card:hover { transform: translateY(-4px); box-shadow: 0 12px 24px rgba(0,0,0,0.06); }
.card-meta { font-size: 0.85rem; color: var(--text-muted); margin-bottom: 16px; display: flex; align-items: center; gap: 8px; flex-wrap: wrap;}
.tag { background: #f0f0f0; padding: 4px 10px; border-radius: 99px; font-weight: 600; font-size: 0.75rem; color: var(--primary); }
.card-title { font-size: 1.25rem; font-weight: 700; margin-bottom: 12px; line-height: 1.3; letter-spacing: -0.01em; }
.featured-main .card-title { font-size: 2.5rem; letter-spacing: -0.03em; margin-bottom: 20px;}
.featured-secondary .card-title { font-size: 1.5rem; }
.card-excerpt { color: var(--text-muted); margin-bottom: 24px; flex-grow: 1; }
.card-author { font-size: 0.9rem; font-weight: 500; display: flex; align-items: center; gap: 12px; margin-top: auto;}
.author-avatar { width: 32px; height: 32px; border-radius: 50%; background: #e0e0e0; display: flex; align-items: center; justify-content: center; font-size: 0.75rem; color: #555; font-weight: 600;}

.stats-block { background: #f9f9f9; border-radius: 8px; padding: 24px; margin-bottom: 24px; display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; border: 1px solid #f0f0f0; }
.stat-item { display: flex; flex-direction: column; }
.stat-value { font-size: 1.75rem; font-weight: 800; color: var(--accent); letter-spacing: -0.02em; line-height: 1.1; margin-bottom: 4px;}
.stat-label { font-size: 0.85rem; color: var(--text-muted); line-height: 1.4; }

.filters-section { margin-bottom: 32px; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 16px; }
.filters-scroll { overflow-x: auto; -webkit-overflow-scrolling: touch; padding-bottom: 8px; margin-bottom: -8px; flex-grow: 1; }
.filters-scroll::-webkit-scrollbar { height: 0; }
.category-filters { display: flex; gap: 8px; }
.filter-pill {
  padding: 8px 16px; border-radius: 99px; font-size: 0.9rem; font-weight: 500;
  background: var(--card-bg); border: 1px solid var(--border); color: var(--text-muted);
  white-space: nowrap; transition: all 0.2s;
}
.filter-pill:hover { border-color: var(--text-muted); color: var(--text-main); }
.filter-pill.active { background: var(--text-main); color: #fff; border-color: var(--text-main); }

.search-box { position: relative; width: 100%; max-width: 300px; }
.search-box input {
  width: 100%; padding: 10px 16px 10px 40px; border-radius: 8px;
  border: 1px solid var(--border); font-size: 0.9rem;
  font-family: inherit; outline: none; transition: border-color 0.2s;
}
.search-box input:focus { border-color: var(--accent); }
.search-icon { position: absolute; left: 14px; top: 50%; transform: translateY(-50%); width: 16px; height: 16px; stroke: var(--text-muted); stroke-width: 2; fill: none;}

.news-grid { display: grid; grid-template-columns: 1fr; gap: 24px; margin-bottom: 48px; }
@media (min-width: 768px) { .news-grid { grid-template-columns: repeat(2, 1fr); } }
@media (min-width: 1024px) { .news-grid { grid-template-columns: repeat(3, 1fr); } }

.news-card { display: flex; }

.no-results { text-align: center; padding: 64px 0; color: var(--text-muted); font-size: 1.1rem; display: none; width: 100%; grid-column: 1 / -1; }

.load-more-container { text-align: center; margin-bottom: 80px; }
.btn-load { padding: 12px 24px; border: 1px solid var(--border); border-radius: 8px; background: var(--card-bg); font-weight: 500; font-size: 1rem; cursor: pointer; transition: all 0.2s; color: var(--text-main); }
.btn-load:hover { border-color: var(--primary); background: #f9f9f9; }

.cta-banner {
  background: var(--primary); color: #fff; border-radius: 16px; padding: 64px 24px;
  text-align: center; margin-bottom: 80px;
}
.cta-banner h2 { font-size: 2.5rem; margin-bottom: 16px; letter-spacing: -0.02em; }
.cta-banner p { color: #a1a1aa; margin-bottom: 40px; font-size: 1.15rem; max-width: 600px; margin-left: auto; margin-right: auto; }
.cta-actions { display: flex; gap: 16px; justify-content: center; margin-bottom: 40px; flex-wrap: wrap;}
.btn-accent { background: var(--accent); color: #fff; border: 1px solid var(--accent); }
.btn-accent:hover { background: #005bb5; border-color: #005bb5; }
.btn-white { background: #fff; color: var(--primary); border: 1px solid #fff; }
.btn-white:hover { background: #f0f0f0; }

.enterprise-block {
  border-top: 1px solid rgba(255,255,255,0.1); padding-top: 32px;
  font-size: 0.95rem; color: #a1a1aa; display: flex; align-items: center; justify-content: center; flex-wrap: wrap; gap: 16px;
}
.enterprise-block .btn { margin-left: 0; border-color: rgba(255,255,255,0.2); color: #fff; }
.enterprise-block .btn:hover { background: rgba(255,255,255,0.1); }

footer { background: var(--card-bg); border-top: 1px solid var(--border); padding: 64px 0 32px; }
.footer-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 48px 24px; margin-bottom: 64px; }
@media (min-width: 768px) { .footer-grid { grid-template-columns: repeat(4, 1fr); } }
@media (min-width: 1024px) { .footer-grid { grid-template-columns: repeat(6, 1fr); } }

.footer-col h4 { font-size: 0.85rem; font-weight: 600; margin-bottom: 20px; color: var(--text-main); }
.footer-col ul { display: flex; flex-direction: column; gap: 12px; }
.footer-col a { color: var(--text-muted); font-size: 0.85rem; transition: color 0.2s; }
.footer-col a:hover { color: var(--accent); }

.footer-bottom { border-top: 1px solid var(--border); padding-top: 32px; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 16px; color: var(--text-muted); font-size: 0.85rem; }
.footer-status { display: flex; align-items: center; gap: 8px; }
.status-dot { width: 8px; height: 8px; background: #10b981; border-radius: 50%; }

.hidden { display: none !important; }
EOF

